record.field:
website = env.ref('members_club.website_industry')
to_deactivate = [ 'website_blog.opt_blog_cover_post', 'website_blog.opt_blog_post_read_next', 'website_blog.opt_posts_loop_show_author', 'website_event.event_time', 'website_event.opt_events_list_columns', 'website_sale.product_quantity', 'website_sale.products_attributes', 'website_sale.products_categories_top', 'website_sale.products_shop_title', 'website_sale.search', 'website_sale.sort', 'website.footer_custom', 'website.header_social_links', 'website.header_text_element', 'website.template_footer_centered', 'website.template_header_default', 'website.homepage', 'website.contactus', ] to_activate = [ 'website_blog.opt_blog_list_view', 'website_sale.header_hide_empty_cart_link', 'website.footer_copyright_content_width_fluid', 'website.header_call_to_action', 'website.header_navbar_pills_style', 'website.header_width_full', 'website.template_footer_minimalist', 'website.template_header_vertical', 'website.template_header_vertical_align_center', ]
ctx = {'website_id': website.id}
for xml_id in to_deactivate: env.ref(xml_id).with_context(**ctx).write({'active': False}) for xml_id in to_activate: env.ref(xml_id).with_context(**ctx).write({'active': True})
def record_url(xmlid): return env.ref(xmlid).website_url
menus = env['website.menu'] base_domain = [('website_id', '=', website.id)] top_menu = menus.search(base_domain + [('parent_id', '=', False)], limit=1)
menus.search(base_domain + [('url', 'in', ['/blog', '/appointment'])]).unlink()
# Menu items of the design, in navbar order. /, /shop and /event are added by # website, website_sale and website_event. for name, url, sequence in [ ('Home', '/', 10), ('Memberships', '/shop', 20), ('Events', '/event', 30), ('News', record_url('members_club.blog_blog_1'), 40), ('Donations', '/donations', 50), ]: menu = menus.search(base_domain + [('url', '=', url)], limit=1) if menu: menu.write({'name': name, 'sequence': sequence}) else: menus.create({ 'name': name, 'url': url, 'sequence': sequence, 'website_id': website.id, 'parent_id': top_menu.id, })
def record_id(xmlid): return str(env.ref(xmlid).id)
# Views reference records by database id or by url: replace the exported # xmlid placeholders by the actual ids and urls. MARKS = { '__EXPORT_FILTER_XMLID__': record_id, '__EXPORT_RES_ID_XMLID__': record_id, '__EXPORT_SLUG_XMLID__': record_url, }
def resolve_marks(content): for mark, resolve in MARKS.items(): while mark in content: start = content.index(mark) end = content.index(mark, start + len(mark)) + len(mark) xmlid = content[start + len(mark):end - len(mark)] try: resolved = resolve(xmlid) except ValueError: resolved = '0' content = content[:start] + resolved + content[end:] return content
for view in env['ir.ui.view'].sudo().search([('website_id', '=', website.id)]): arch = view.arch_db or '' new_arch = resolve_marks(arch) if new_arch != arch: view.write({'arch_db': new_arch})
